.pm-chapter-container {
  font-family: system-ui, -apple-system, sans-serif;
  color: var(--ink, #1a1a1a);
  background-color: var(--paper, #ffffff);
  line-height: 1.6;
  padding: 20px;
  max-width: 900px;
  margin: 0 auto;
  box-sizing: border-box;
}

.pm-chapter-container * {
  box-sizing: border-box;
}

.pm-section {
  margin-bottom: 40px;
  border-left: 4px solid var(--line, #e0e0e0);
  padding-left: 20px;
}

.pm-section-title {
  font-size: 24px;
  font-weight: 600;
  margin-bottom: 16px;
  color: var(--ink, #1a1a1a);
}

.pm-text {
  font-size: 16px;
  margin-bottom: 16px;
  color: var(--ink, #1a1a1a);
}

.pm-small {
  font-size: 14px;
  color: var(--muted, #666666);
}

.pm-diagram-wrapper {
  background: var(--paper, #ffffff);
  border: 1px solid var(--line, #e0e0e0);
  padding: 20px;
  margin: 20px 0;
  border-radius: 4px;
  overflow-x: auto;
}

.pm-arch-svg {
  width: 100%;
  height: auto;
  min-width: 320px;
  display: block;
}

.pm-block {
  stroke: var(--ink, #1a1a1a);
  stroke-width: 1.5;
  fill: var(--paper, #ffffff);
  transition: fill 0.3s ease;
}

.pm-block-input { fill: #f0f4f8; }
.pm-block-pos { fill: #e3f2fd; }
.pm-block-encoder { fill: #e0f7fa; }
.pm-block-decoder { fill: #fff3e0; }
.pm-block-output { fill: #f3e5f5; }

.pm-label {
  font-size: 12px;
  fill: var(--ink, #1a1a1a);
  font-family: monospace;
}

.pm-label-sub {
  font-size: 10px;
  fill: var(--muted, #666666);
  font-family: monospace;
}

.pm-connector {
  stroke: var(--line, #cccccc);
  stroke-width: 2;
  fill: none;
  marker-end: url(#arrow-head);
}

.pm-flow-path {
  transition: opacity 0.3s ease;
}

.pm-controls {
  margin-top: 15px;
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

.pm-btn {
  font-size: 14px;
  padding: 8px 16px;
  background: var(--paper, #ffffff);
  border: 1px solid var(--line, #cccccc);
  color: var(--ink, #1a1a1a);
  cursor: pointer;
  border-radius: 4px;
  transition: background 0.2s;
}

.pm-btn:hover {
  background: var(--line, #f0f0f0);
}

.pm-btn-source {
  border-color: var(--muted, #999999);
  color: var(--muted, #666666);
}

.pm-btn-concept {
  border-color: var(--accent, #007bff);
  color: var(--accent, #007bff);
}

.pm-stepper-container {
  border: 1px solid var(--line, #e0e0e0);
  padding: 20px;
  margin: 20px 0;
  border-radius: 4px;
}

.pm-stepper-nav {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 15px;
}

.pm-step-label {
  font-size: 14px;
  color: var(--muted, #666666);
}

.pm-step-content {
  min-height: 80px;
  margin-bottom: 15px;
}

.pm-step-title {
  font-size: 16px;
  font-weight: 600;
  margin-bottom: 8px;
  color: var(--ink, #1a1a1a);
}

.pm-step-text {
  font-size: 15px;
  color: var(--ink, #1a1a1a);
}

.pm-stepper-actions {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  border-top: 1px solid var(--line, #e0e0e0);
  padding-top: 15px;
}

.pm-note-block {
  background: #f9f9f9;
  border-left: 3px solid var(--accent, #007bff);
  padding: 15px;
  margin-top: 20px;
}

@media (prefers-reduced-motion: reduce) {
  .pm-flow-path, .pm-block {
    transition: none;
  }
}

@media (max-width: 480px) {
  .pm-text { font-size: 15px; }
  .pm-btn { font-size: 13px; padding: 6px 12px; }
}
