(function() {
  var container = document.getElementById('ch1_arch_flow');
  if (!container) return;

  var flowToggle = document.getElementById('pm-flow-toggle');
  var flowPath = document.getElementById('pm-flow-highlight');
  var stepPrev = document.getElementById('pm-step-prev');
  var stepNext = document.getElementById('pm-step-next');
  var stepIndicator = document.getElementById('pm-step-indicator');
  var stepContent = document.getElementById('pm-step-content');

  var isFlowActive = false;
  var currentStep = 0;

  var stepsData = [
    {
      title: "步骤 1: 嵌入与位置编码结合",
      text: "原始输入 token 首先转换为输入嵌入向量，然后加上对应的位置编码向量。同样，目标序列转换为输出嵌入后也加上位置编码。"
    },
    {
      title: "步骤 2: 解码器输入偏移",
      text: "在解码器中，为了预测位置 i 的输出，输入序列被向右偏移一位。这意味着在时刻 i，模型看到的是时刻 i-1 及之前的真实输出（或生成的 token），从而实现了自回归的因果约束。"
    }
  ];

  function updateFlow() {
    if (!flowPath) return;
    if (isFlowActive) {
      flowPath.style.opacity = '1';
    } else {
      flowPath.style.opacity = '0';
    }
  }

  function updateStepper() {
    if (!stepIndicator || !stepContent) return;
    var data = stepsData[currentStep];
    stepIndicator.textContent = '步骤 ' + (currentStep + 1) + ' / ' + stepsData.length;

    var titleEl = stepContent.querySelector('.pm-step-title');
    var textEl = stepContent.querySelector('.pm-step-text');

    if (titleEl) titleEl.textContent = data.title;
    if (textEl) textEl.textContent = data.text;

    if (stepPrev) stepPrev.disabled = (currentStep === 0);
    if (stepNext) {
      stepNext.disabled = (currentStep === stepsData.length - 1);
      stepNext.textContent = (currentStep === stepsData.length - 1) ? '完成' : '下一步';
    }
  }

  if (flowToggle) {
    flowToggle.addEventListener('click', function() {
      isFlowActive = !isFlowActive;
      updateFlow();
    });
  }

  if (stepPrev) {
    stepPrev.addEventListener('click', function() {
      if (currentStep > 0) {
        currentStep--;
        updateStepper();
      }
    });
  }

  if (stepNext) {
    stepNext.addEventListener('click', function() {
      if (currentStep < stepsData.length - 1) {
        currentStep++;
        updateStepper();
      }
    });
  }

  initializeState();

  function initializeState() {
    updateFlow();
    updateStepper();
  }
})();
